    let need, cp;
    if (c >= 0xc2 && c <= 0xdf) { need = 1; cp = c & 0x1f; }
    else if (c >= 0xe0 && c <= 0xef) { need = 2; cp = c & 0x0f; }
    else if (c >= 0xf0 && c <= 0xf4) { need = 3; cp = c & 0x07; }
    else return null;
    if (i + need > n) return null;
    for (let k = 0; k < need; k++) {
      const d = b[i++];
      if ((d & 0xc0) !== 0x80) return null;
      cp = (cp << 6) | (d & 0x3f);
    }
    if (need === 2 && (cp < 0x800 || (cp >= 0xd800 && cp <= 0xdfff))) return null;
    if (need === 3 && (cp < 0x10000 || cp > 0x10ffff)) return null;
    if (cp >= 0x10000) { cp -= 0x10000; u.push(0xd800 + (cp >> 10), 0xdc00 + (cp & 0x3ff)); }
    else u.push(cp);
