  for (let i = 0; i < s.length; i++) if (s.charCodeAt(i) >= 0x80) { ascii = false; break; }
  if (ascii) return { text: s, lossy: false, enc: "ascii" };
  const b = _strToBytes(s);
  if (b[0] === 0xff && b[1] === 0xfe) return { text: _utf16(b, 2, true), lossy: false, enc: "utf-16le" };
  if (b[0] === 0xfe && b[1] === 0xff) return { text: _utf16(b, 2, false), lossy: false, enc: "utf-16be" };
  if (b[0] === 0xef && b[1] === 0xbb && b[2] === 0xbf) {
    const t = _utf8Strict(b, 3);
    if (t !== null) return { text: t, lossy: false, enc: "utf-8" };
  }
  let even = 0, odd = 0;
  const lim = Math.min(b.length, 4096);
  for (let i = 0; i < lim; i++) if (b[i] === 0) { if (i % 2) odd++; else even++; }
  if (odd > lim * 0.08 && odd > even * 2) return { text: _utf16(b, 0, true), lossy: false, enc: "utf-16le" };
  if (even > lim * 0.08 && even > odd * 2) return { text: _utf16(b, 0, false), lossy: false, enc: "utf-16be" };
